        public static readonly string FixedSchema = @"<?xml version=""1.0"" encoding=""UTF-8""?>\n<xs:schema xmlns:xs=""http://www.w3.org/2001/XMLSchema"" xmlns:doc=""http://www.w3.org/2000/10/XMLSchema-doc"" xmlns:ns=""urn:OECD:StandardAuditFile-Tax:PT_1.04_01"" xmlns:vc=""http://www.w3.org/2007/XMLSchema-versioning"" attributeFormDefault=""unqualified"" elementFormDefault=""qualified"" id=""SAF-T_PT"" targetNamespace=""urn:OECD:StandardAuditFile-Tax:PT_1.04_01"" version=""1.04_01"" vc:minVersion=""1.1"">\n<xs:annotation>\n<xs:documentation>\n<doc:Title>Standard Audit File - Portuguese Version</doc:Title>\n<doc:Subject>Standard Audit File - Portuguese Version</doc:Subject>\n<doc:Copyright>Copyright OECD</doc:Copyright>\n<doc:Version>\n<doc:Number>1.04_01</doc:Number>\n<doc:Status>Production</doc:Status>\n</doc:Version>\n<doc:Author>Autoridade Tributaria e Aduaneira</doc:Author>\n<doc:ModificationDate>2022-05-17</doc:ModificationDate>\n</xs:documentation>\n</xs:annotation>\n<!-- Estrutura do ficheiro SAFT-PT-->\n<xs:element name=""AuditFile"">\n<xs:complexType>\n<xs:sequence>\n<xs:element ref=""Header"" minOccurs=""1""/>\n<xs:element name=""MasterFiles"">\n<xs:complexType>\n<xs:sequence>\n<xs:element ref=""GeneralLedgerAccounts"" minOccurs=""0""/>\n<xs:element ref=""Customer"" minOccurs=""0""/>\n<xs:element ref=""Supplier"" minOccurs=""0""/>\n<xs:element ref=""Product"" minOccurs=""0""/>\n<xs:element ref=""TaxTable"" minOccurs=""0""/>\n</xs:sequence>\n</xs:complexType>\n</xs:element>\n<xs:element ref=""GeneralLedgerEntries"" minOccurs=""0""/>\n<xs:element ref=""SourceDocuments"" minOccurs=""0""/>\n</xs:sequence>\n</xs:complexType>\n<!-- Constraint-->\n<xs:key name=""AccountIDConstraint"">\n<xs:selector xpath=""MasterFiles/GeneralLedgerAccounts/Account""/>\n<xs:field xpath=""AccountID""/>\n</xs:key>\n<xs:keyref name=""GroupingCodeConstraint"" refer=""AccountIDConstraint"">\n<xs:selector xpath=""MasterFiles/GeneralLedgerAccounts/Account""/>\n<xs:field xpath=""Grouping